#include <stdio.h>
#include <string.h>

int minNumberOfFrogs(const char *s) {
    int stage[4] = {0, 0, 0, 0};
    int active = 0, answer = 0;

    for (const char *p = s; *p; ++p) {
        switch (*p) {
            case 'c':
                stage[0]++;
                active++;
                if (active > answer) answer = active;
                break;
            case 'r':
                if (stage[0] == 0) return -1;
                stage[0]--; stage[1]++;
                break;
            case 'o':
                if (stage[1] == 0) return -1;
                stage[1]--; stage[2]++;
                break;
            case 'a':
                if (stage[2] == 0) return -1;
                stage[2]--; stage[3]++;
                break;
            case 'k':
                if (stage[3] == 0) return -1;
                stage[3]--; active--;
                break;
            default:
                return -1;
        }
    }
    return active == 0 ? answer : -1;
}

